<script>
$(function(){var t=$('#landed-cost-table'),e=$.fn.dataTable.render.text(),classes={DRAFT:'app-status-neutral',SUBMITTED:'app-status-warning',APPROVED:'app-status-info',POSTED:'app-status-success',VOID:'app-status-danger'};var table=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:t.data('url'),data:function(d){d.date_from=$('#lc-filter-date-from').val();d.date_to=$('#lc-filter-date-to').val();d.status=$('#lc-filter-status').val();}},order:[[1,'desc']],buttons:[window.erpExcelButton(t)],columns:[{data:'document_number',render:function(v,type,r){if(type!=='display')return v;return '<a class="fw-semibold text-decoration-none" href="'+e.display(r.show_url)+'">'+e.display(v)+'</a><small class="text-secondary d-block">'+e.display(r.allocations_count+' allocation')+'</small>'; }},{data:'business_date',render:e.display},{data:'basis_label',render:e.display},{data:'total_amount',className:'text-end',render:function(v){return e.display(Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}));}},{data:'status_label',render:function(v,type,r){return type==='display'?'<span class="badge '+(classes[r.status]||'app-status-neutral')+'">'+e.display(v)+'</span>':v;}},{data:null,orderable:false,searchable:false,className:'text-end text-nowrap',render:function(v,type,r){if(type!=='display')return '';var a=['<a class="btn btn-sm btn-app-soft" href="'+e.display(r.show_url)+'" title="ดูรายละเอียด" aria-label="ดูรายละเอียด"><i class="bx bx-show" aria-hidden="true"></i></a>'];if(r.can_submit)a.push('<button class="btn btn-sm btn-app-soft js-lc-action" data-url="'+e.display('/purchasing/landed-costs/'+r.id+'/submit')+'" data-title="ส่ง Landed Cost เพื่ออนุมัติ?" title="ส่งอนุมัติ" aria-label="ส่งอนุมัติ"><i class="bx bx-send" aria-hidden="true"></i></button>');if(r.can_approve)a.push('<button class="btn btn-sm btn-app-primary js-lc-action" data-url="'+e.display('/purchasing/landed-costs/'+r.id+'/approve')+'" data-title="อนุมัติ Landed Cost?" title="อนุมัติ" aria-label="อนุมัติ"><i class="bx bx-check" aria-hidden="true"></i></button>');if(r.can_post)a.push('<button class="btn btn-sm btn-app-primary js-lc-action" data-url="'+e.display('/purchasing/landed-costs/'+r.id+'/post')+'" data-title="Post Landed Cost?" title="Post" aria-label="Post"><i class="bx bx-send" aria-hidden="true"></i></button>');if(r.can_void)a.push('<button class="btn btn-sm btn-outline-danger js-lc-action" data-url="'+e.display('/purchasing/landed-costs/'+r.id+'/void')+'" data-title="ยกเลิกเอกสาร?" title="ยกเลิก" aria-label="ยกเลิก"><i class="bx bx-x" aria-hidden="true"></i></button>');return a.join(' ');}}]}));$('#lc-filter-date-from,#lc-filter-date-to,#lc-filter-status').on('change',function(){table.ajax.reload();});$('#lc-filter-search').on('input',function(){clearTimeout(window.lcSearchTimer);window.lcSearchTimer=setTimeout(function(){table.search($('#lc-filter-search').val()).draw();},300);});$('#lc-filter-reset').on('click',function(){$('#lc-filter-search,#lc-filter-date-from,#lc-filter-date-to,#lc-filter-status').val('');table.search('').ajax.reload();});t.on('click','.js-lc-action',function(){var b=$(this);Swal.fire({icon:'warning',title:b.data('title'),showCancelButton:true,confirmButtonText:'ยืนยัน',cancelButtonText:'ยกเลิก'}).then(function(x){if(!x.isConfirmed)return;b.prop('disabled',true);$.post(b.data('url'),{_token:$('meta[name=csrf-token]').attr('content')}).done(function(r){Swal.fire({icon:'success',text:r.msg||'ดำเนินการแล้ว',timer:1200,showConfirmButton:false});table.ajax.reload(null,false);}).fail(function(x){Swal.fire({icon:'error',text:x.responseJSON?.message||'ดำเนินการไม่สำเร็จ'});}).always(function(){b.prop('disabled',false);});});});});
</script>
